import * as THREE from 'three';
import type { AssetStore } from '../assets/AssetStore';
import type { MobDef } from '../entities/catalog';
import models from '../entities/entityModels.json';
import { texturePath } from '../models/resourceLocation';
import { MeshBatch, vertexColor } from './buildMesh';
import { loadTexture } from './textures';

/** Baked vanilla geometry, generated by scripts/DumpEntityModels.java. */
interface PartJson {
  /** x, y, z, xRot, yRot, zRot, xScale, yScale, zScale (pixels / radians) */
  pose: number[];
  visible: boolean;
  /** cubes → polygons → 4 vertices × (x, y, z, u, v), u/v normalised to the layer's texture size. */
  cubes: number[][][];
  children: Record<string, PartJson>;
}

interface LayerJson {
  tex: [number, number];
  root: PartJson;
}

export const ENTITY_MODELS = models as unknown as Record<string, LayerJson>;

type Vec3 = [number, number, number];

interface PolygonVisit {
  part: string;
  /** Vertices in entity model space (pixels, y down). */
  verts: Vec3[];
  uvs: [number, number][];
  /** Outward normal in model space. */
  normal: THREE.Vector3;
}

function walk(
  part: PartJson,
  parent: THREE.Matrix4,
  name: string,
  pose: MobDef['pose'],
  visit: (p: PolygonVisit) => void,
) {
  if (!part.visible) return;
  const [x, y, z, xr, yr, zr, xs, ys, zs] = part.pose;
  const extra = pose?.[name.split('/').pop()!] ?? [0, 0, 0];
  const m = parent
    .clone()
    .multiply(new THREE.Matrix4().makeTranslation(x, y, z))
    .multiply(new THREE.Matrix4().makeRotationFromEuler(new THREE.Euler(xr + extra[0], yr + extra[1], zr + extra[2], 'ZYX')))
    .multiply(new THREE.Matrix4().makeScale(xs, ys, zs));
  const normalMatrix = new THREE.Matrix3().getNormalMatrix(m);

  for (const cube of part.cubes) {
    const center = new THREE.Vector3();
    let n = 0;
    for (const poly of cube) for (let i = 0; i < 20; i += 5) center.add(new THREE.Vector3(poly[i], poly[i + 1], poly[i + 2])), n++;
    center.divideScalar(n || 1);

    for (const poly of cube) {
      const local = [0, 5, 10, 15].map((i) => new THREE.Vector3(poly[i], poly[i + 1], poly[i + 2]));
      const normal = new THREE.Vector3().subVectors(local[1], local[0]).cross(new THREE.Vector3().subVectors(local[2], local[0]));
      if (normal.lengthSq() === 0) continue; // zero-thickness face (e.g. flat planes seen edge-on)
      const faceCenter = local.reduce((a, v) => a.add(v), new THREE.Vector3()).divideScalar(4);
      if (normal.dot(faceCenter.sub(center)) < 0) normal.negate();
      visit({
        part: name,
        verts: local.map((v) => v.applyMatrix4(m).toArray() as Vec3),
        uvs: [0, 5, 10, 15].map((i) => [poly[i + 3], poly[i + 4]] as [number, number]),
        normal: normal.applyMatrix3(normalMatrix).normalize(),
      });
    }
  }
  for (const [child, p] of Object.entries(part.children)) walk(p, m, name ? `${name}/${child}` : child, pose, visit);
}

/** Directional shading Minecraft-style: top 1.0, bottom 0.5, north/south 0.8, east/west 0.6. */
function shade(n: THREE.Vector3): number {
  return Math.min(1, n.x * n.x * 0.6 + n.y * n.y * ((3 + n.y) / 4) + n.z * n.z * 0.8);
}

export async function buildMobObject(store: AssetStore, mob: MobDef): Promise<THREE.Group> {
  // Entity space is y-down with the feet at y = 24 and the face towards -z;
  // flip it into world space so the mob stands on y = 0 looking at +z.
  const root = new THREE.Group();
  root.scale.set(1 / 16, -1 / 16, -1 / 16);
  root.position.y = 1.5;

  for (let li = 0; li < mob.layers.length; li++) {
    const layer = mob.layers[li];
    const model = ENTITY_MODELS[layer.model];
    if (!model) continue;
    const tex = await loadTexture(store, layer.texture);
    const batch = new MeshBatch();
    walk(model.root, new THREE.Matrix4(), '', mob.pose, ({ verts, uvs, normal }) => {
      // Model-space y/z are flipped by the root transform, so flip the normal the same way for shading.
      const s = layer.emissive ? 1 : shade(new THREE.Vector3(normal.x, -normal.y, -normal.z));
      // Minecraft's quad order (0,1,2,3) is the reverse of MeshBatch's corner order.
      const order = [0, 3, 2, 1];
      batch.quad(order.map((i) => verts[i]), order.map((i) => [uvs[i][0], 1 - uvs[i][1]] as [number, number]), vertexColor(s, 0xffffff));
    });
    const mesh = batch.toMesh(tex, THREE.FrontSide, li);
    if (layer.emissive) {
      const mat = mesh.material as THREE.MeshBasicMaterial;
      mat.blending = THREE.AdditiveBlending;
      mat.transparent = true;
      mat.depthWrite = false;
    }
    mesh.renderOrder = li;
    root.add(mesh);
  }
  const wrapper = new THREE.Group();
  wrapper.add(root);
  return wrapper;
}

export interface UVRect {
  part: string;
  x0: number;
  y0: number;
  x1: number;
  y1: number;
}

/** Texture regions (in the model's texture pixel space) used by each face, for the UV overlay. */
export function layerUVRects(modelKey: string): { tex: [number, number]; rects: UVRect[] } | undefined {
  const model = ENTITY_MODELS[modelKey];
  if (!model) return undefined;
  const [w, h] = model.tex;
  const rects: UVRect[] = [];
  walk(model.root, new THREE.Matrix4(), '', undefined, ({ part, uvs }) => {
    const us = uvs.map((u) => u[0] * w);
    const vs = uvs.map((u) => u[1] * h);
    const r = { part, x0: Math.min(...us), y0: Math.min(...vs), x1: Math.max(...us), y1: Math.max(...vs) };
    if (r.x1 > r.x0 && r.y1 > r.y0) rects.push(r);
  });
  return { tex: model.tex, rects };
}

/** Files a mob's appearance depends on; used for source badges and cache keys. */
export function mobDeps(mob: MobDef): string[] {
  return [...new Set(mob.layers.flatMap((l) => [texturePath(l.texture), `${texturePath(l.texture)}.mcmeta`]))];
}
